<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesListRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityUserVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityTrustedClientVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesUidVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVersionVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesItem;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityVersionVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\Create\PlatformIdentityCreateParams;
use PHPUnit\Framework\TestCase;

final class PlatformIdentityCreateParamsUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new PlatformIdentityCreateParams();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrDefault(PlatformIdentityUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrDefault(PlatformIdentityUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrDefault(PlatformIdentityUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrDefault(PlatformIdentityUserVO::from($userOtherValue))->value());
        $relyingPartyOneValue = new RelyingPartyRef('one');
        $relyingPartyOtherValue = new RelyingPartyRef('other');
        $copy = $value->relyingParty($relyingPartyOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new RelyingPartyRef('one'), $value->getRelyingParty());
        $this->assertNotEquals(new RelyingPartyRef('other'), $value->getRelyingParty());
        $this->assertEquals(new RelyingPartyRef('one'), $value->getRelyingPartyOrDefault(PlatformIdentityRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $this->assertNotEquals(new RelyingPartyRef('other'), $value->getRelyingPartyOrDefault(PlatformIdentityRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $value->unsetRelyingParty();
        $this->assertEquals(new RelyingPartyRef('other'), $value->getRelyingPartyOrDefault(PlatformIdentityRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $this->assertNotEquals(new RelyingPartyRef('one'), $value->getRelyingPartyOrDefault(PlatformIdentityRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $trustedClientOneValue = new TrustedClientRef('one');
        $trustedClientOtherValue = new TrustedClientRef('other');
        $copy = $value->trustedClient($trustedClientOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClient());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClient());
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClientOrDefault(PlatformIdentityTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClientOrDefault(PlatformIdentityTrustedClientVO::from($trustedClientOtherValue))->value());
        $value->unsetTrustedClient();
        $this->assertEquals(new TrustedClientRef('other'), $value->getTrustedClientOrDefault(PlatformIdentityTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('one'), $value->getTrustedClientOrDefault(PlatformIdentityTrustedClientVO::from($trustedClientOtherValue))->value());
        $rolesOneValue = new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        ));
        $rolesOtherValue = new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('other'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('other')),
            PlatformIdentityRolesVersionVO::from(2)
        ));
        $copy = $value->roles($rolesOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )), $value->getRoles());
        $this->assertNotEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('other'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('other')),
            PlatformIdentityRolesVersionVO::from(2)
        )), $value->getRoles());
        $this->assertEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )), $value->getRolesOrDefault(PlatformIdentityRolesVO::from($rolesOtherValue))->value());
        $this->assertNotEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('other'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('other')),
            PlatformIdentityRolesVersionVO::from(2)
        )), $value->getRolesOrDefault(PlatformIdentityRolesVO::from($rolesOtherValue))->value());
        $value->unsetRoles();
        $this->assertEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('other'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('other')),
            PlatformIdentityRolesVersionVO::from(2)
        )), $value->getRolesOrDefault(PlatformIdentityRolesVO::from($rolesOtherValue))->value());
        $this->assertNotEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )), $value->getRolesOrDefault(PlatformIdentityRolesVO::from($rolesOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrDefault(PlatformIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrDefault(PlatformIdentityVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrDefault(PlatformIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrDefault(PlatformIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
